#!/usr/bin/env node
import {existsSync, readFileSync, rmSync, writeFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {spawnSync} from 'node:child_process';

const target = 'youtube/etf-100-euro-kompletter-weg-v3';
if (existsSync(target)) rmSync(target, {recursive:true, force:true});

const scenes = [
  {type:'hybrid',tier:'hero',layout:'journey',chapter:'Hook',title:'Wo gehen deine 100 Euro hin?',text:'Du investierst 100 Euro in einen ETF. Sekunden später steht ein Anteil in deinem Depot. Aber hier ist der Teil, den fast niemand sieht: Deine 100 Euro werden in diesem Moment nicht automatisch in hundert kleine Stücke geteilt und direkt an hunderte Unternehmen geschickt. Also wohin gehen sie wirklich? Wir verfolgen jetzt genau diese 100 Euro – vom Klick auf Kaufen bis zu dem, was du am Ende tatsächlich besitzt.',mechanic:'money-click-to-etf-layer',technique:'camera-follow-100-euro-through-etf',family:'camera-journey',viewer:['100 €','KAUFEN','ETF-ANTEIL','WOHIN GEHT DAS GELD?'],image:'YouTube Bild 01 - 100 Euro ETF Hook.png',imageSituation:'A real investor desk with a broker purchase confirmation showing 100 euros on the left, a clearly recognizable ETF share certificate in the center, and a subtle visible layer of many underlying company holdings behind it; the causal connection is visible in one cinematic frame.',context:'Broker purchase desk, ETF share certificate and underlying company holdings.',match:'Directly shows the hook question: 100 euros are used to buy an ETF share, while the underlying holdings are a separate layer.',labels:['100 €','ETF-Anteil']},
  {type:'animation',tier:'hero',layout:'journey',chapter:'Vom Klick zur Börse',title:'Der Kaufauftrag startet',text:'Alles beginnt bei deinem Broker. Auf deinem Verrechnungskonto liegen 100 Euro, du wählst einen ETF und drückst auf Kaufen. Der Broker erzeugt daraus einen Börsenauftrag mit Stückzahl oder Betrag, Handelsplatz und Preisregel. Dieser Auftrag verlässt dein Konto nicht als magisches Geldpaket. Er wird an einen Handelsplatz geleitet, an dem Kauf- und Verkaufsangebote zusammengeführt werden. Erst wenn zwei Seiten zusammenpassen, entsteht ein Handel.',mechanic:'broker-order-route',technique:'order-ticket-camera-route',family:'process-flow',viewer:['BROKER','KAUFAUFTRAG','BÖRSE','MATCH']},
  {type:'image',tier:'support',chapter:'Vom Klick zur Börse',title:'Was im Depot landet',text:'Nach dem Handel siehst du keinen Aktienkorb im Depot, sondern zunächst einen ETF-Anteil als eigenes Wertpapier.',image:'YouTube Bild 03 - ETF Anteil im Depot.png',imageSituation:'A literal securities custody scene: a single stylized ETF share certificate is booked into a clean depot folder, while a separate blurred basket of companies remains clearly in the background, emphasizing that the depot entry is one fund share rather than individual company shares.',context:'Securities depot after a completed ETF purchase.',match:'Shows exactly what appears in the investor depot after the trade: one ETF fund share, not many individual shares.',labels:['ETF-Anteil','Depot']},
  {type:'animation',tier:'hero',layout:'match',chapter:'Sekundärmarkt',title:'Käufer und Verkäufer treffen sich',text:'Das ist der erste wichtige Unterschied: Meist kaufst du einen bereits existierenden ETF-Anteil von einem anderen Marktteilnehmer. Dein Geld geht bei diesem konkreten Börsengeschäft zunächst an die Verkaufsseite. Im Gegenzug wird der ETF-Anteil deinem Depot gutgeschrieben. Genau deshalb ist die Vorstellung falsch, deine 100 Euro würden beim Klick sofort einzeln an Apple, Microsoft oder andere Unternehmen überwiesen. Für den normalen Anleger beginnt die Reise am Sekundärmarkt.',mechanic:'buyer-seller-etf-swap',technique:'two-sided-trade-swap',family:'comparison',viewer:['KÄUFER','100 €','BÖRSE','ETF-ANTEIL','VERKÄUFER']},
  {type:'image',tier:'support',chapter:'Sekundärmarkt',title:'Geld und Anteil wechseln die Seite',text:'Deine 100 Euro und der ETF-Anteil wechseln beim Börsenhandel also zwischen Käufer und Verkäufer die Seiten.',image:'YouTube Bild 05 - ETF Käufer Verkäufer.png',imageSituation:'Two clearly separated real-world trading counterparties at one stylized exchange counter: the buyer side passes a 100 euro payment while the seller side passes one ETF share certificate in the opposite direction, both transfers visible in the same frame.',context:'Literal secondary-market ETF trade between buyer and seller.',match:'Shows the exact exchange described by the voiceover: money moves one way and the ETF share the other way.',labels:['Käufer','Verkäufer','100 €','ETF-Anteil']},
  {type:'animation',tier:'support',layout:'ladder',chapter:'Sekundärmarkt',title:'Market Maker und Spread',text:'Damit du nicht minutenlang auf irgendeinen Verkäufer warten musst, stellen professionelle Market Maker häufig fortlaufend Kauf- und Verkaufspreise. Du siehst deshalb einen Geldkurs und einen Briefkurs. Die Differenz dazwischen nennt man Spread. Market Maker sind nicht einfach ein unsichtbarer Geldverteiler. Sie sorgen vor allem dafür, dass handelbare Preise vorhanden sind und können Bestände aufnehmen oder wieder abgeben, wenn Käufer und Verkäufer nicht exakt gleichzeitig auftauchen.',mechanic:'bid-ask-liquidity',technique:'living-bid-ask-ladder',family:'data-viz',viewer:['GELDKURS','SPREAD','BRIEFKURS','MARKET MAKER']},
  {type:'hybrid',tier:'hero',layout:'basket',chapter:'Primärmarkt',title:'Creation und Redemption',text:'Jetzt kommt die zweite Ebene, die man in der Broker-App kaum sieht. Bestimmte große Marktteilnehmer, sogenannte Authorized Participants, können große Pakete von ETF-Anteilen direkt mit dem Fonds schaffen oder zurückgeben. Dafür liefern sie einen passenden Wertpapierkorb oder erhalten ihn zurück. Dieser Creation-und-Redemption-Mechanismus verbindet den Börsenhandel mit dem tatsächlichen Fondsportfolio. Genau hier entsteht die Brücke zwischen dem ETF-Anteil, den du handelst, und den Wertpapieren im Fonds.',mechanic:'ap-basket-create-redeem',technique:'basket-to-etf-block-transformation',family:'spatial-3d',viewer:['AUTHORIZED PARTICIPANT','WERTPAPIERKORB','ETF-BLOCK','FONDS'],image:'YouTube Bild 07 - Creation Redemption.png',imageSituation:'A literal institutional creation/redemption setting: an Authorized Participant delivers a basket of many stylized securities into the ETF fund side and receives a block of ETF shares back, with both sides clearly connected in one premium 3D scene.',context:'Primary-market ETF creation/redemption between Authorized Participant and fund.',match:'Directly depicts the hidden bridge between a securities basket and newly created ETF share blocks.',labels:['Wertpapierkorb','ETF-Anteile','Fonds']},
  {type:'image',tier:'support',chapter:'Primärmarkt',title:'Was der Fonds im Hintergrund hält',text:'Im Hintergrund besitzt der Fonds ein eigenes Portfolio aus Wertpapieren oder anderen vertraglich festgelegten Positionen.',image:'YouTube Bild 08 - ETF Fondsportfolio.png',imageSituation:'A literal fund custody environment containing a diversified portfolio of company securities arranged inside one clearly marked ETF fund pool, separated from the investor depot and from the management company.',context:'ETF fund portfolio and custody layer.',match:'Shows that the fund itself holds a portfolio of securities or contractually defined positions.',labels:['Fondsportfolio']},
  {type:'data',tier:'hero',layout:'converge',chapter:'Preis und Fondswert',title:'Warum Marktpreis und Fondswert verbunden bleiben',text:'Warum entfernt sich der Börsenpreis dann nicht völlig vom Wert des Fonds? Stell dir vor, ein ETF-Anteil würde deutlich teurer gehandelt als der entsprechende Anteil am Fondsportfolio. Professionelle Marktteilnehmer hätten dann einen Anreiz, die Preisdifferenz zu nutzen. Umgekehrt gilt das bei einem zu niedrigen Börsenpreis. Creation, Redemption und Arbitrage helfen deshalb, größere Abweichungen zwischen Marktpreis und Fondsvermögen zu begrenzen. Sie garantieren aber nicht, dass beide Werte in jeder Sekunde identisch sind.',mechanic:'market-price-nav-gap-closes',technique:'dual-value-convergence-field',family:'data-viz',viewer:['MARKTPREIS','FONDSWERT','ARBITRAGE','ANNÄHERUNG'],data:'Educational mechanism only. No synthetic market series. The animation explains relative convergence conceptually and must not imply exact intraday equality.'},
  {type:'animation',tier:'support',layout:'rules',chapter:'Index und Strategie',title:'Der Index ist ein Regelwerk',text:'Was der Fonds überhaupt besitzen soll, bestimmt nicht der Name ETF, sondern seine Strategie. Bei einem Index-ETF folgt diese Strategie einem Index. Der Index ist im Grunde ein Regelwerk: Welche Wertpapiere dürfen hinein, wie werden sie gewichtet, wann wird neu sortiert und welche Unternehmen fliegen wieder heraus? Der ETF versucht anschließend, die Wertentwicklung dieses Regelwerks möglichst genau nachzubilden.',mechanic:'index-rules-rebalance',technique:'rule-cards-reweight-holdings',family:'timeline',viewer:['REGELN','AUFNAHME','GEWICHTUNG','REBALANCING']},
  {type:'image',tier:'support',chapter:'Replikation',title:'Physische Nachbildung',text:'Bei physischer Nachbildung hält der Fonds tatsächlich Wertpapiere aus dem Index – vollständig oder als repräsentative Auswahl.',image:'YouTube Bild 11 - Physische ETF Replikation.png',imageSituation:'A literal ETF fund portfolio physically holding a recognizable selection of many stylized company securities corresponding to an index list placed beside the fund, with a clear one-to-many relationship.',context:'Physical ETF replication inside the fund portfolio.',match:'Shows that the fund physically holds securities from the index, either fully or as a representative selection.',labels:['Index','Fondsportfolio']},
  {type:'animation',tier:'hero',layout:'compare',chapter:'Replikation',title:'Sampling und synthetische Replikation',text:'Bei einem sehr breiten Index muss der Fonds nicht zwingend jede einzelne Position exakt eins zu eins halten. Beim Sampling wird eine Auswahl so zusammengestellt, dass sie den Index möglichst gut repräsentiert. Bei synthetischer Replikation kann zusätzlich ein Swap eingesetzt werden: Der Fonds hält ein Portfolio und tauscht dessen Wertentwicklung vertraglich gegen die gewünschte Indexrendite. Deshalb lohnt sich ein Blick in die Fondsunterlagen, statt aus dem Wort ETF auf die genaue Konstruktion zu schließen.',mechanic:'sampling-versus-swap',technique:'replication-method-split-transform',family:'comparison',viewer:['SAMPLING','AUSWAHL','SWAP','INDEXRENDITE']},
  {type:'hybrid',tier:'support',layout:'network',chapter:'Diversifikation',title:'Was breite Streuung wirklich macht',text:'Für dich bleibt der zentrale Punkt: Du besitzt Anteile am Fonds, nicht hunderte einzelne Aktienpositionen in deinem Namen. Ist der zugrunde liegende Index breit gestreut, verteilt sich das wirtschaftliche Risiko des Fonds auf viele Unternehmen, Länder und Branchen. Fällt nur ein kleines Unternehmen stark, muss das den gesamten ETF deshalb nicht im gleichen Ausmaß treffen. Diese Streuung reduziert Einzelwertrisiken – sie beseitigt aber nicht das Risiko des gesamten Marktes.',mechanic:'single-company-shock-network',technique:'diversification-node-shock',family:'simulation',viewer:['UNTERNEHMEN','LÄNDER','BRANCHEN','BREIT GESTREUT'],image:'YouTube Bild 13 - Breite ETF Streuung.png',imageSituation:'A literal broad global ETF portfolio represented by many distinct company holdings grouped across several countries and industries, with one small company position highlighted as only one part of the total fund.',context:'Broadly diversified equity ETF portfolio.',match:'Shows the fund spreading exposure across many companies, countries and sectors rather than putting everything into one company.',labels:['Unternehmen','Länder','Branchen']},
  {type:'image',tier:'support',chapter:'Diversifikation',title:'ETF heißt nicht automatisch breit gestreut',text:'Ein Themen- oder Branchen-ETF kann trotz des Namens ETF stark auf wenige Unternehmen oder einen Bereich konzentriert sein.',image:'YouTube Bild 14 - Themen ETF Konzentration.png',imageSituation:'A literal concentrated thematic ETF portfolio where most of the fund is visibly clustered around one industry and a small group of companies, contrasted inside the same scene with unused empty diversification space.',context:'Concentrated sector or thematic ETF portfolio.',match:'Directly shows that an ETF can still be concentrated in one sector or a few companies.',labels:['Themen-ETF','Konzentration']},
  {type:'animation',tier:'support',layout:'flow',chapter:'Erträge',title:'Was mit Dividenden passiert',text:'Wenn Unternehmen im Fonds Dividenden zahlen, verschwinden diese Erträge nicht. Sie fließen zunächst in das Fondsvermögen. Bei einem ausschüttenden ETF werden Erträge nach den Fondsregeln an die Anleger ausgezahlt. Bei einem thesaurierenden ETF werden sie im Fonds wiederangelegt. Wichtig ist: Eine Dividende ist kein kostenloses Zusatzgeld. Rund um die Ausschüttung verändert sich auch der Unternehmenswert, und damit wirkt sich die Zahlung auf die Bewertung der Position aus.',mechanic:'dividend-fund-split',technique:'dividend-stream-distribute-reinvest',family:'process-flow',viewer:['DIVIDENDEN','FONDS','AUSSCHÜTTEND','THESAURIEREND']},
  {type:'data',tier:'hero',layout:'costs',chapter:'Kosten',title:'Wo Kosten anfallen',text:'Jetzt zu den Kosten. Beim Kauf können Ordergebühren entstehen, und der Spread kann deinen Einstieg verteuern. Im Fonds selbst fallen laufende Kosten an. Eine Kostenquote von 0,2 Prozent entspricht bei 100 Euro rechnerisch ungefähr 20 Cent pro Jahr, wenn wir Kursänderungen ignorieren. Bei 10.000 Euro wären es ungefähr 20 Euro. In der Realität hängt die Abweichung zum Index zusätzlich von Transaktionskosten, Steuern auf Fondsebene und der Qualität der Nachbildung ab.',mechanic:'cost-layers-reduce-value',technique:'money-stack-cost-slices',family:'data-viz',viewer:['100 €','SPREAD','ORDERKOSTEN','0,2 %','20 CENT','10.000 € → 20 €'],data:'Educational arithmetic: 100 € × 0.2% = 0.20 €; 10,000 € × 0.2% = 20 €. Ignores market movement and is not a return forecast.'},
  {type:'image',tier:'support',chapter:'Kosten',title:'Wo du die Details findest',text:'Kosten, Replikationsmethode und wichtige Risiken findest du nicht im Werbeslogan, sondern in den offiziellen Fondsinformationen.',image:'YouTube Bild 17 - ETF Fondsunterlagen.png',imageSituation:'A literal investor desk with official ETF product documents opened to clearly separated sections for costs, replication method and risks, while a flashy marketing leaflet is pushed aside and visually secondary.',context:'Official ETF product documentation reviewed before purchase.',match:'Shows the viewer checking the actual fund documents for costs, replication method and risks.',labels:['Kosten','Replikation','Risiken']},
  {type:'animation',tier:'hero',layout:'drawdown',chapter:'Risiko',title:'Warum 100 Euro zu 80 Euro werden können',text:'Warum zeigt dein Depot morgen vielleicht nur noch 92 Euro? Nicht weil die App willkürlich eine Zahl ändert. Der Wert der Positionen, die der ETF abbildet, verändert sich am Markt. Steigen viele große Bestandteile, steigt typischerweise auch der Fonds. Fallen sie, fällt auch der ETF. Aus 100 Euro können bei einem Rückgang von 20 Prozent rechnerisch 80 Euro werden. Das ist kein Prognosewert, sondern ein Beispiel für echtes Marktrisiko.',mechanic:'holdings-fall-etf-value-follows',technique:'portfolio-drawdown-camera-drop',family:'camera-journey',viewer:['100 €','MARKT FÄLLT','80 €','BEISPIEL: -20 %']},
  {type:'hybrid',tier:'support',layout:'network',chapter:'Risiko',title:'Diversifikation ist kein Schutzschild',text:'Breite Streuung hilft gegen das Risiko eines einzelnen Unternehmens, aber nicht gegen einen allgemeinen Börsenrückgang. Wenn viele Länder und Branchen gleichzeitig fallen, kann auch ein globaler ETF deutlich im Minus stehen. Genau deshalb ist Diversifikation kein Schutzschild gegen jede Schwankung, sondern eine Methode, bestimmte Risiken besser zu verteilen. Wer kurzfristig sicher auf das Geld angewiesen ist, sollte diesen Unterschied verstehen, bevor er Aktien-ETFs als Parkplatz benutzt.',mechanic:'global-shock-network',technique:'multi-sector-downturn-wave',family:'simulation',viewer:['EINZELRISIKO','MARKTRISIKO','GLOBALER RÜCKGANG'],image:'YouTube Bild 19 - Globaler ETF Rueckgang.png',imageSituation:'A literal diversified global ETF portfolio containing many companies, countries and sectors, but with a broad market downturn visibly affecting many groups at the same time, making the overall fund value decline despite diversification.',context:'Broad global equity ETF during a market-wide downturn.',match:'Shows that diversification can reduce single-company risk while a broad market decline can still pull the whole ETF down.',labels:['Breit gestreut','Marktrisiko']},
  {type:'image',tier:'support',chapter:'Insolvenz und Verwahrung',title:'Brokerpleite ist nicht Kursverlust',text:'Eine Brokerpleite ist etwas anderes als ein Kursverlust: Deine Depotwertpapiere sind grundsätzlich keine normale Bankeinlage.',image:'YouTube Bild 20 - Brokerpleite Depotwerte.png',imageSituation:'A literal brokerage insolvency context: the broker company office is marked as insolvent while the investor ETF securities remain separately shown in a custody/depot record rather than inside a bank deposit account.',context:'Broker insolvency with separately held securities in custody.',match:'Shows the distinction between a failed broker company and the securities held in the investor depot.',labels:['Broker','Depotwertpapiere']},
  {type:'animation',tier:'support',layout:'custody',chapter:'Insolvenz und Verwahrung',title:'Wertpapiere können übertragen werden',text:'Wertpapiere im Depot werden für dich verwahrt. Gerät der Broker in Insolvenz, bedeutet das deshalb nicht automatisch, dass deine ETF-Anteile wirtschaftlich verschwinden. Grundsätzlich kannst du die Herausgabe beziehungsweise Übertragung deiner Wertpapiere verlangen, sofern keine besonderen Gegenansprüche bestehen. Das schützt dich jedoch nicht vor fallenden Kursen. Ein ETF, der währenddessen 20 Prozent verliert, bleibt auch nach der Übertragung ein ETF mit diesem niedrigeren Marktwert.',mechanic:'custody-transfer-after-broker-failure',technique:'certificate-escapes-failed-broker',family:'document-motion',viewer:['BROKER INSOLVENT','DEPOT','ÜBERTRAGUNG','ETF BLEIBT ETF']},
  {type:'animation',tier:'hero',layout:'vault',chapter:'Insolvenz und Verwahrung',title:'Fondsvermögen ist getrennt',text:'Auch auf Fondsebene gibt es eine wichtige Trennung. Das Fondsvermögen wird getrennt vom eigenen Vermögen der Kapitalverwaltungsgesellschaft gehalten und verwahrt. Vereinfacht gesagt: Die Fondsgesellschaft soll die Wertpapiere des Fonds nicht wie ihr eigenes Firmenkonto behandeln können. Diese rechtliche Trennung ist ein Schutz gegen bestimmte Insolvenzrisiken der Gesellschaft. Sie ist aber wieder kein Schutz vor schlechten Märkten, einem schwachen Index oder Verlusten der Vermögenswerte selbst.',mechanic:'management-company-separated-from-fund-assets',technique:'split-vault-insolvency-isolation',family:'spatial-3d',viewer:['FONDSGESELLSCHAFT','FONDSVERMÖGEN','GETRENNT','MARKTRISIKO BLEIBT']},
  {type:'image',tier:'support',chapter:'Was du wirklich besitzt',title:'Dein rechtlicher und wirtschaftlicher Kern',text:'Am Ende besitzt du also ETF-Anteile mit einem wirtschaftlichen Anspruch auf das getrennt gehaltene Fondsvermögen.',image:'YouTube Bild 23 - Was du beim ETF besitzt.png',imageSituation:'A literal final ownership scene: the investor holds one ETF fund share certificate that is clearly linked to a separately held fund asset pool containing many securities, without suggesting direct personal ownership of each underlying company share.',context:'Investor ownership of ETF fund shares linked economically to segregated fund assets.',match:'Directly shows what the investor actually owns: ETF shares connected to the fund assets.',labels:['ETF-Anteil','Fondsvermögen']},
  {type:'animation',tier:'hero',layout:'recap',chapter:'Zusammenfassung',title:'Die ganze Reise in einem Zug',text:'Fassen wir die Reise deiner 100 Euro zusammen. Du drückst beim Broker auf Kaufen. Der Auftrag gelangt an einen Handelsplatz und trifft auf eine Gegenseite. Du erhältst einen ETF-Anteil. Creation und Redemption verbinden diesen Handel im Hintergrund mit dem Fondsportfolio. Der Fonds folgt seiner Index- oder Anlagestrategie, hält beziehungsweise repliziert die vorgesehenen Vermögenswerte, sammelt Erträge und trägt Kosten. Deren Marktwert entscheidet am Ende darüber, was dein ETF-Anteil wert ist.',mechanic:'full-etf-money-journey',technique:'continuous-etf-system-flythrough',family:'camera-journey',viewer:['100 €','BÖRSE','ETF-ANTEIL','FONDS','WERTPAPIERE','WERT']},
  {type:'animation',tier:'support',layout:'checks',chapter:'Zusammenfassung',title:'Drei Checks vor dem Kauf',text:'Vor dem Kauf prüfst du deshalb drei Dinge: Was bildet der Index wirklich ab, wie breit ist er gestreut und welche Kosten sowie Risiken hat genau dieser Fonds? Dann weißt du nicht nur, wie man einen ETF kauft, sondern was man tatsächlich kauft. Im nächsten Video können wir genau darauf aufbauen und MSCI World, FTSE All-World und andere Weltindizes direkt miteinander vergleichen.',mechanic:'three-etf-checks-lock-in',technique:'kinetic-three-check-cards',family:'kinetic-type',viewer:['1  INDEX','2  STREUUNG','3  KOSTEN + RISIKO','VERSTEHEN, WAS DU KAUFST']},
];

const types = scenes.map((scene)=>scene.type).join(',');
const scaffold = spawnSync(process.execPath,[resolve('scripts/scaffold-finanzneo-youtube.mjs'),'--target',target,'--title','Was passiert wirklich mit deinen 100 € im ETF?','--types',types],{stdio:'inherit'});
if (scaffold.status !== 0) process.exit(scaffold.status ?? 1);

const write = (path,content)=>writeFileSync(resolve(target,path),content);
const wordsOf = (text)=>text.trim().split(/\s+/).filter(Boolean);
let cursor = 0;
const ranges = scenes.map((scene)=>{const count=wordsOf(scene.text).length;const range={start:cursor,end:cursor+count-1};cursor+=count;return range;});
const fullScript = scenes.map((scene)=>scene.text).join('\n\n');
if (wordsOf(fullScript).length !== cursor) throw new Error('Word range mismatch.');

const research = `# Recherche und Quellen\n\nDatenstand der fachlichen Recherche: 05.09.2026. Motion-V3-Neuaufbau: 09.09.2026.\n\n## Kernquellen\n\n1. Verbraucherzentrale — ETF-Kauf: Auswahlkriterien, Stand 12.03.2026\nhttps://www.verbraucherzentrale.de/wissen/geld-versicherungen/sparen-und-anlegen/etfkauf-auf-diese-kriterien-sollten-sie-bei-der-auswahl-achten-16605\n- ETF = börsengehandelter Investmentfonds; Auswahl u. a. nach Streuung, Kosten und Fondsmerkmalen.\n\n2. Verbraucherzentrale — Vorteile und Nachteile von ETFs, Stand 21.07.2025\nhttps://www.verbraucherzentrale.de/wissen/geld-versicherungen/sparen-und-anlegen/welche-vorteile-und-nachteile-haben-etfs-16603\n- ETFs sind nicht risikofrei; Börsenhandel und Orderkosten sind relevant.\n\n3. Verbraucherzentrale — Wie baut ein ETF einen Index nach?\nhttps://www.verbraucherzentrale.de/wissen/geld-versicherungen/sparen-und-anlegen/wie-baut-ein-etf-einen-index-nach-16608\n- Physische Replikation, optimiertes Sampling und weitere Konstruktionsmerkmale.\n\n4. Deutsche Börse — ETF / Creation-Redemption\nhttps://live.deutsche-boerse.com/en/know-how/lexikon/etf-exchange-traded-fund\nhttps://live.deutsche-boerse.com/news/aus-dem-etf-magazin-einfach-clever-konstruiert\n- Börsenhandel, Market Maker, Authorized Participants sowie Creation/Redemption.\n\n5. BaFin — Das kleine ABC der Geldanlage, 2026\nhttps://www.bafin.de/SharedDocs/Downloads/DE/Broschuere/dl_b_ABC_der_Geldanlage_leichte_sprache.pdf?__blob=publicationFile&v=4\n- Fondsvermögen ist vom Vermögen der Kapitalverwaltungsgesellschaft getrennt.\n\n6. BaFin — Einlagensicherung und Anlegerentschädigung\nhttps://bafin.de/DE/verbraucherinnen-verbraucher/themen-finanzprodukte/geldanlage/einlagensicherung-anlegerentschaedigung/einlagensicherung-anlegerentschaedigung.html\n- Wertpapiere/Fondsanteile sind keine Einlagen; verwahrte Wertpapiere können grundsätzlich herausverlangt oder übertragen werden.\n\n7. ESMA — UCITS Artikel 52/53\nhttps://www.esma.europa.eu/publications-and-data/interactive-single-rulebook/ucits/article-52\nhttps://www.esma.europa.eu/publications-and-data/interactive-single-rulebook/ucits/article-53\n- Regulatorische Diversifikations- und Indexregeln.\n\n## Rechenbeispiele\n\n- 0,2 % von 100 € = 0,20 €.\n- 0,2 % von 10.000 € = 20 €.\n- 100 € minus 20 % = 80 €.\n- Nur didaktische Größenordnungen; keine Prognosen.\n\n## Grenzen\n\nKeine individuelle Anlageberatung. Keine Garantie, dass jeder ETF breit gestreut ist. Sonder-/Fondsvermögen schützt nicht vor Marktverlusten. Steuerdetails werden nicht vertieft.\n`;

write('01-script/script-fliess-text.txt',fullScript+'\n');
write('01-script/kapitel-dramaturgie.md',`# Kapitel und Dramaturgie\n\n1. Hook: Wo gehen die 100 € wirklich hin?\n2. Börsenhandel: Auftrag, Käufer/Verkäufer, Market Maker.\n3. Primärmarkt: Creation/Redemption und Fondsportfolio.\n4. Index/Replikation: Regeln, physisch, Sampling, Swap.\n5. Diversifikation und Konzentration.\n6. Erträge und Kosten.\n7. Markt- und Insolvenzrisiken.\n8. Payoff: gesamte Reise + drei Checks.\n\nKeine neutrale Einleitung. Jeder Abschnitt beantwortet eine zuvor geöffnete Frage und öffnet die nächste.\n`);
write('01-script/retention-plan.md',`# Retention-Plan\n\n- 0–20 s: 100-€-Mysterium sofort sichtbar; keine Begrüßung.\n- Nach dem Kauf: Überraschung, dass normale ETF-Käufe zunächst Sekundärmarktgeschäfte sind.\n- Primärmarkt als zweite Ebene mit klarer visueller Auflösung.\n- Wechsel zwischen 3D-Reisen, echten Bildbeats, Datenvisualisierung, Split-Comparisons und Simulation.\n- Keine statische Bildszene länger als 7 s nach realen Wortzeiten.\n- Motion-Events spätestens alle ca. 2–3,5 s.\n- Midpoint-Payoff: Diversifikation schützt nicht vor allgemeinem Marktrisiko.\n- Schluss: komplette Reise in einer durchgehenden Kamera-Erklärung + drei konkrete Prüfungen.\n`);
write('05-projektdateien/briefing.md',`# Briefing\n\n- Thema: Was passiert wirklich mit 100 € bei einem ETF-Kauf?\n- Zielgruppe: Finanzanfänger.\n- Ziel: Sekundärmarkt, Fondsportfolio, Replikation, Kosten und Risiken als eine nachvollziehbare Reise verstehen.\n- Zielzeit: 8–10 Minuten.\n- Skript: ${cursor} Wörter.\n- Bildwelt bleibt unverändert: finanzneo-connected-studio-v3 / finanzneo-same-world-v1.\n- Video wird vollständig neu aufgebaut; alte Motion-V2-Animationen werden nicht übernommen.\n`);
write('05-projektdateien/recherche-quellen.md',research);

