const sourceFor = (scene,index) => {
  const id=`szene-${String(index+1).padStart(2,'0')}`;
  const exportName=`YouTubeScene${String(index+1).padStart(2,'0')}Animation`;
  const events = scene.tier==='hero' ? ['Szene steht','Erster Impuls','Zweite Ebene','Verbindung','Kontrast','Folge','Erklärung','Resultat'] : ['Szene steht','Impuls','Verbindung','Folge','Kontrast','Resultat'];
  const body=motionBody(scene);
  return `import React from 'react';\nimport {AbsoluteFill, interpolate, spring, useCurrentFrame, useVideoConfig} from 'remotion';\n\nexport const MECHANIC_ID = ${esc(scene.mechanic)};\nexport const VISUAL_TECHNIQUE_ID = ${esc(scene.technique)};\nexport const COMPOSITION_FAMILY_ID = ${esc(scene.family)};\nexport const VIEWER_TEXT = ${JSON.stringify(scene.viewer)};\nexport const MOTION_EVENTS = ${JSON.stringify(events)};\nexport const ANIMATION_NARRATIVE = {START:${esc(scene.title+' beginnt als klarer Ausgangszustand.')},MECHANISM:${esc('Die zentrale ETF-Mechanik verändert mehrere sichtbare Elemente nacheinander.')},RESULT:${esc('Das Ergebnis bleibt am Ende klar und lesbar stehen.')}};\n\nconst C=${JSON.stringify(color)};\nconst clamp={extrapolateLeft:'clamp',extrapolateRight:'clamp'} as const;\nconst pct=(frame:number,duration:number,a:number,b:number)=>interpolate(frame,[a*duration,b*duration],[0,1],clamp);\n\nexport const ${exportName}: React.FC = () => {\n  const frame=useCurrentFrame();\n  const {durationInFrames,fps}=useVideoConfig();\n  const p1=pct(frame,durationInFrames,0.00,0.12);\n  const p2=spring({frame,fps,config:{damping:20,stiffness:110,mass:0.9},durationInFrames:Math.max(18,Math.round(durationInFrames*0.18))});\n  const p3=pct(frame,durationInFrames,0.10,0.28);\n  const p4=pct(frame,durationInFrames,0.22,0.42);\n  const p5=pct(frame,durationInFrames,0.36,0.56);\n  const p6=pct(frame,durationInFrames,0.50,0.70);\n  const p7=pct(frame,durationInFrames,0.64,0.84);\n  const p8=pct(frame,durationInFrames,0.78,0.96);\n  const settle=interpolate(frame,[0.90*durationInFrames,0.99*durationInFrames],[0,1],clamp);\n  return <AbsoluteFill data-scene-id=${esc(id)} style={{background:'#000000',overflow:'hidden',fontFamily:'Arial, sans-serif'}}>${body}<div style={{position:'absolute',left:0,right:0,bottom:0,height:6,background:'#102019'}}><div style={{height:'100%',width:(100*p8)+'%',background:C.green,opacity:0.35+0.4*settle}}/></div></AbsoluteFill>;\n};\n\n/* Motion-V3-Designnotiz: Diese Szene ist als eigenständige mehrstufige Erklärmechanik gebaut. Sie beginnt bereits mit sichtbarem Kontext, verändert Position, Maßstab, Deckkraft, Rotation beziehungsweise Größe über mehrere zeitlich getrennte Beats und hält das verständliche Resultat. Die Animation ist framebasiert und deterministisch. Sichtbare Texte sind ausschließlich kurze deutsche Zuschauerlabels aus VIEWER_TEXT. Produktionsnotizen und Regieanweisungen werden niemals als JSX-Text ausgegeben. */\n`;
};

