const promptFor=(scene,i)=>`FLOW_AGENT_PROTOCOL: finanzneo-flow-sequential-v1\nFINAL FILE NAME: ${scene.image}\nGenerate exactly ONE image. Wait until it is fully complete. Rename it immediately to the exact final file name. QA this image before continuing. If it fails, regenerate the same image number. Never batch or queue images.\n\nLITERAL_REAL_WORLD_SITUATION: ${scene.imageSituation}\nREAL_WORLD_CONTEXT_ANCHOR: ${scene.context}\nVOICEOVER_VISUAL_MATCH: ${scene.match}\nTRANSFERABILITY_TEST: PASS - This composition is specific to this exact ETF mechanism and could not explain five unrelated finance topics without major changes.\nVISUAL_STRATEGY: literal\nMETAPHOR_JUSTIFICATION: none\n\nIMAGE PROMPT:\nCreate a premium horizontal 16:9 stylized 3D FinanzNeo explainer image. ${scene.imageSituation} Use a single seamless deep-black environment with high-contrast cinematic lighting, emerald and mint structural accents, restrained gold only for money/value, and red-orange only if risk/loss is explicitly part of this beat. Keep objects large and readable for YouTube. No photorealism, no dashboard, no generic icon collage, no text paragraphs. ${scene.labels?.length?`Only these short German object labels may appear when useful: ${scene.labels.join(', ')}.`:'Do not render any text.'}\n\n${world}`;
let allPrompts=`FINANZNEO FLOW SINGLE-JOB FILE\nFLOW_AGENT_PROTOCOL: finanzneo-flow-sequential-v1\nGenerate exactly ONE image at a time. Rename it immediately. QA it before the next image. Literal first, creative second. Final images go to 03-szenen/00-ALLE-BILDER-HIER-REIN/.\n\nTHUMBNAIL\nFINAL FILE NAME: YouTube Thumbnail - Wo gehen 100 Euro im ETF hin.png\nGenerate exactly ONE image. Rename it immediately and QA before continuing.\nCreate a premium horizontal 16:9 stylized 3D FinanzNeo thumbnail: a large 100 euro value token on the left enters a clearly recognizable ETF share in the center, while the right side reveals that the share connects to a deep field of many underlying companies. Strong unanswered visual question, large focal objects, deep black background, emerald/mint structure, gold 100 euro value, no text inside the image.\n\n${world}\n`;
scenes.forEach((scene,i)=>{if(scene.image){const p=promptFor(scene,i);write(`03-szenen/szene-${String(i+1).padStart(2,'0')}/bildprompt.txt`,p);allPrompts+=`\n━━ SZENE ${String(i+1).padStart(2,'0')} ━━\n${p}\n`;}else allPrompts+=`\n━━ SZENE ${String(i+1).padStart(2,'0')} — REMOTION ━━\nDO NOT GENERATE AN IMAGE FOR THIS SCENE.\n`;});
